<?php
if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Studio OS V13.7 — final-only release integrity + immutable release history checks */
function tuff_beatz_integrity_report($id){$id=(int)$id;$issues=array();$status=(string)(get_post_meta($id,'_tb_request_status',true)?:'new');$files=function_exists('tuff_beatz_vault_files')?tuff_beatz_vault_files($id):array();$ids=array();$finals=array();foreach($files as $f){$fid=(string)($f['id']??'');if(!$fid){$issues[]=array('severity'=>'high','code'=>'file-missing-id','message'=>'A vault record is missing its canonical file ID.');continue;}if(isset($ids[$fid]))$issues[]=array('severity'=>'high','code'=>'duplicate-file-id','message'=>'Duplicate vault file identity detected: '.$fid);$ids[$fid]=1;$type=function_exists('tuff_beatz_vault_asset_type')?tuff_beatz_vault_asset_type($f):'';if(!in_array($type,array('source','stem','mix','master','final','attachment','document'),true))$issues[]=array('severity'=>'medium','code'=>'invalid-asset-type','message'=>'File '.$fid.' has an invalid canonical asset type.');if($type==='final'&&empty($f['archived']))$finals[$fid]=$f;}
$manifest=function_exists('tuff_beatz_delivery_manifest')?tuff_beatz_delivery_manifest($id):array();$history=function_exists('tuff_beatz_delivery_manifest_history')?tuff_beatz_delivery_manifest_history($id):array();$acceptance=function_exists('tuff_beatz_delivery_acceptance_record')?tuff_beatz_delivery_acceptance_record($id):array();$acceptance_history=function_exists('tuff_beatz_delivery_acceptance_history')?tuff_beatz_delivery_acceptance_history($id):array();$confirmed=(string)get_post_meta($id,'_tb_delivery_confirmed_at',true);$confirmed_by=(int)get_post_meta($id,'_tb_delivery_confirmed_by',true);if($manifest){if(empty($manifest['manifest_id']))$issues[]=array('severity'=>'high','code'=>'manifest-missing-id','message'=>'Delivery manifest exists without a manifest ID.');if(empty($manifest['files']))$issues[]=array('severity'=>'high','code'=>'manifest-empty','message'=>'Delivery manifest exists without final release assets.');foreach((array)($manifest['files']??array()) as $mf){$fid=(string)($mf['id']??'');if(($mf['asset_type']??'')!=='final')$issues[]=array('severity'=>'critical','code'=>'manifest-nonfinal-asset','message'=>'Official release manifest contains a non-Final asset.');if(!$fid||!isset($ids[$fid]))$issues[]=array('severity'=>'high','code'=>'manifest-orphan-file','message'=>'Delivery manifest references a vault asset that no longer exists: '.($fid?:'unknown'));}}
if($manifest&&$history){$last=end($history);if(($last['manifest_id']??'')!==($manifest['manifest_id']??'')||(int)($last['release_version']??0)!==(int)($manifest['release_version']??0))$issues[]=array('severity'=>'high','code'=>'manifest-history-mismatch','message'=>'Current release manifest does not match the latest immutable release-history entry.');}
if($status==='delivery'&&!$manifest)$issues[]=array('severity'=>'high','code'=>'delivery-without-manifest','message'=>'Project is in Delivery but has no official Final release manifest.');if($status==='completed'&&!$confirmed)$issues[]=array('severity'=>'critical','code'=>'completed-without-acceptance','message'=>'Project is completed without a delivery confirmation timestamp.');if($confirmed&&!$confirmed_by)$issues[]=array('severity'=>'high','code'=>'confirmation-without-user','message'=>'Delivery confirmation exists without an accepting user.');if($acceptance){if(!$confirmed)$issues[]=array('severity'=>'high','code'=>'acceptance-without-confirmation','message'=>'Acceptance record exists without the canonical confirmation timestamp.');if(($acceptance['manifest_id']??'')!==($manifest['manifest_id']??''))$issues[]=array('severity'=>'high','code'=>'acceptance-manifest-mismatch','message'=>'Acceptance record does not match the current delivery manifest.');if((int)($acceptance['release_version']??0)!==(int)($manifest['release_version']??0))$issues[]=array('severity'=>'critical','code'=>'accepted-release-changed','message'=>'The current release version differs from the recorded client acceptance.');if($acceptance_history){$last_accept=end($acceptance_history);if(($last_accept['acceptance_id']??'')!==($acceptance['acceptance_id']??''))$issues[]=array('severity'=>'high','code'=>'acceptance-history-mismatch','message'=>'Current acceptance does not match the latest immutable acceptance-history entry.');}}
$approved=(string)get_post_meta($id,'_tb_approved_mix_file',true);if($approved&&!isset($ids[$approved]))$issues[]=array('severity'=>'high','code'=>'approved-mix-missing','message'=>'Approved mix points to a vault file that no longer exists.');if(in_array($status,array('delivery','completed'),true)&&!$finals)$issues[]=array('severity'=>'critical','code'=>'release-assets-missing','message'=>'Delivery/completed project has no active canonical Final asset.');return array('project_id'=>$id,'status'=>$status,'checked_at'=>current_time('mysql'),'file_count'=>count($files),'release_asset_count'=>count($finals),'manifest_history_count'=>count($history),'acceptance_history_count'=>count($acceptance_history),'issue_count'=>count($issues),'issues'=>$issues);}
function tuff_beatz_integrity_has_blocking_issue($id){foreach(tuff_beatz_integrity_report($id)['issues'] as $x)if(in_array($x['severity'],array('critical','high'),true))return true;return false;}
function tuff_beatz_integrity_store_snapshot($id){$r=tuff_beatz_integrity_report($id);update_post_meta((int)$id,'_tb_integrity_v13',$r);return $r;}
function tuff_beatz_integrity_watch_meta($meta_id,$object_id,$meta_key,$meta_value){if(get_post_type($object_id)!=='tb_request')return;if(!in_array($meta_key,array('_tb_request_status','_tb_delivery_manifest_v12','_tb_delivery_manifest_history_v137','_tb_delivery_acceptance_v12','_tb_delivery_acceptance_history_v137','_tb_delivery_confirmed_at','_tb_delivery_confirmed_by','_tb_approved_mix_file','_tb_vault_files'),true))return;static $busy=false;if($busy)return;$busy=true;tuff_beatz_integrity_store_snapshot($object_id);$busy=false;}
add_action('added_post_meta','tuff_beatz_integrity_watch_meta',90,4);add_action('updated_post_meta','tuff_beatz_integrity_watch_meta',90,4);add_action('deleted_post_meta','tuff_beatz_integrity_watch_meta',90,4);
function tuff_beatz_integrity_workspace(){if(!is_page('project-dashboard')||!is_user_logged_in())return;$id=(int)($_GET['project']??0);if(!$id||!function_exists('tuff_beatz_user_can_view_request')||!tuff_beatz_user_can_view_request($id))return;$r=tuff_beatz_integrity_store_snapshot($id);$can_manage=function_exists('tuff_beatz_auth_is_producer')?tuff_beatz_auth_is_producer($id):current_user_can('edit_post',$id);if(!$can_manage||!$r['issue_count'])return;?><script>document.addEventListener('DOMContentLoaded',function(){var root=document.querySelector('.tb-project-dashboard')||document.querySelector('main');if(!root)return;var box=document.createElement('section');box.className='tb-integrity-panel';box.innerHTML=<?php ob_start();?><div class="tb-integrity-head"><div><small>STUDIO OS V13.7</small><strong>Data Integrity Monitor</strong></div><span><?php echo esc_html((string)$r['issue_count']);?> ISSUE<?php echo $r['issue_count']===1?'':'S';?></span></div><div class="tb-integrity-list"><?php foreach(array_slice($r['issues'],0,8) as $x):?><div class="tb-integrity-item is-<?php echo esc_attr($x['severity']);?>"><b><?php echo esc_html(strtoupper($x['severity']));?></b><p><?php echo esc_html($x['message']);?></p></div><?php endforeach;?></div><?php $html=ob_get_clean();echo wp_json_encode($html);?>;root.insertBefore(box,root.firstChild);});</script><?php }
add_action('wp_footer','tuff_beatz_integrity_workspace',3);
function tuff_beatz_integrity_assets(){if(!is_page('project-dashboard'))return;wp_add_inline_style('tuff-beatz-project-portal','.tb-integrity-panel{max-width:1180px;margin:12px auto 20px;padding:16px;border:1px solid rgba(216,180,90,.2);border-radius:14px;background:rgba(10,10,10,.78)}.tb-integrity-head{display:flex;justify-content:space-between;align-items:center;gap:15px}.tb-integrity-head small{display:block;color:#8f7c4c;font-size:.55rem;letter-spacing:.14em}.tb-integrity-head strong{color:#e8ddc5;font-family:Cinzel,serif}.tb-integrity-head>span{color:#d7b95f;font-size:.6rem;letter-spacing:.1em}.tb-integrity-list{display:grid;gap:7px;margin-top:12px}.tb-integrity-item{display:flex;gap:10px;align-items:flex-start;padding:9px 10px;border-left:2px solid #6d634b;background:rgba(255,255,255,.018)}.tb-integrity-item b{font-size:.52rem;color:#b89a50;min-width:54px}.tb-integrity-item p{margin:0;color:#aaa194;font-size:.66rem}.tb-integrity-item.is-critical{border-left-color:#d4ae49}.tb-integrity-item.is-high{border-left-color:#a88b48}');}
add_action('wp_enqueue_scripts','tuff_beatz_integrity_assets',101);
